-- ============================================================
-- 测试数据验证脚本
-- 用于验证 TestDataGenerator 生成的数据是否符合预期
-- ============================================================

-- 1. 查看各表数据量统计
SELECT 'CATEGORY' AS TableName, COUNT(*) AS Count FROM CATEGORY
UNION ALL SELECT 'TAG', COUNT(*) FROM TAG
UNION ALL SELECT 'VENUE', COUNT(*) FROM VENUE
UNION ALL SELECT 'SEAT_MAP', COUNT(*) FROM SEAT_MAP
UNION ALL SELECT 'SEAT_SECTION', COUNT(*) FROM SEAT_SECTION
UNION ALL SELECT 'SEAT', COUNT(*) FROM SEAT
UNION ALL SELECT 'SHOW', COUNT(*) FROM SHOW
UNION ALL SELECT 'SHOW_TAG', COUNT(*) FROM SHOW_TAG
UNION ALL SELECT 'SHOW_SESSION', COUNT(*) FROM SHOW_SESSION
UNION ALL SELECT 'PRICE_STRATEGY', COUNT(*) FROM PRICE_STRATEGY
UNION ALL SELECT 'PURCHASE_LIMIT', COUNT(*) FROM PURCHASE_LIMIT
ORDER BY TableName;


-- 2. 验证演出数量是否为10场
SELECT 
    'SHOW_COUNT' AS CheckName,
    COUNT(*) AS Actual,
    10 AS Expected,
    CASE WHEN COUNT(*) = 10 THEN 'PASS' ELSE 'FAIL' END AS Status
FROM SHOW;


-- 3. 验证每场演出的场次数（3~5场）
SELECT 
    s.SHOW_NAME,
    COUNT(ss.SESSION_ID) AS SessionCount,
    CASE 
        WHEN COUNT(ss.SESSION_ID) BETWEEN 3 AND 5 THEN 'PASS'
        ELSE 'FAIL'
    END AS Status
FROM SHOW s
LEFT JOIN SHOW_SESSION ss ON s.SHOW_ID = ss.SHOW_ID
GROUP BY s.SHOW_ID, s.SHOW_NAME
ORDER BY s.SHOW_NAME;


-- 4. 验证每个场次的座位数（约200个）
SELECT 
    s.SHOW_NAME,
    ss.SESSION_ID,
    ss.START_TIME,
    ss.SESSION_STATUS,
    COUNT(st.SEAT_ID) AS SeatCount,
    CASE 
        WHEN COUNT(st.SEAT_ID) >= 180 AND COUNT(st.SEAT_ID) <= 220 THEN 'PASS'
        ELSE 'FAIL'
    END AS Status
FROM SHOW_SESSION ss
JOIN SHOW s ON ss.SHOW_ID = s.SHOW_ID
JOIN SEAT_MAP sm ON ss.SEAT_MAP_ID = sm.SEAT_MAP_ID
JOIN SEAT_SECTION sec ON sec.SEAT_MAP_ID = sm.SEAT_MAP_ID
JOIN SEAT st ON st.SEAT_SECTION_ID = sec.SEAT_SECTION_ID
GROUP BY s.SHOW_NAME, ss.SESSION_ID, ss.START_TIME, ss.SESSION_STATUS
ORDER BY ss.SESSION_ID
LIMIT 20;


-- 5. 验证场次状态分布
SELECT 
    SESSION_STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW_SESSION), 2) AS Percentage
FROM SHOW_SESSION
GROUP BY SESSION_STATUS
ORDER BY Count DESC;


-- 6. 验证演出状态分布
SELECT 
    STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW), 2) AS Percentage
FROM SHOW
GROUP BY STATUS
ORDER BY Count DESC;


-- 7. 验证审核状态分布
SELECT 
    AUDIT_STATUS,
    COUNT(*) AS Count,
    ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM SHOW), 2) AS Percentage
FROM SHOW
GROUP BY AUDIT_STATUS
ORDER BY Count DESC;


-- 8. 验证票价策略分布
SELECT 
    PRICE_TYPE,
    COUNT(*) AS Count,
    MIN(PRICE) AS MinPrice,
    MAX(PRICE) AS MaxPrice,
    AVG(PRICE) AS AvgPrice
FROM PRICE_STRATEGY
GROUP BY PRICE_TYPE
ORDER BY PRICE_TYPE;


-- 9. 验证限购策略分布
SELECT 
    LIMIT_TYPE,
    CHANNEL,
    USER_TYPE,
    COUNT(*) AS Count,
    AVG(MAX_BUY_COUNT) AS AvgLimit
FROM PURCHASE_LIMIT
GROUP BY LIMIT_TYPE, CHANNEL, USER_TYPE
ORDER BY LIMIT_TYPE, CHANNEL, USER_TYPE;


-- 10. 验证场馆与座位图关系
SELECT 
    v.VENUE_NAME,
    COUNT(DISTINCT sm.SEAT_MAP_ID) AS SeatMapCount
FROM VENUE v
LEFT JOIN SEAT_MAP sm ON v.VENUE_ID = sm.VENUE_ID
GROUP BY v.VENUE_NAME
ORDER BY SeatMapCount DESC;